pub async fn initialize(app_state: &AppState) -> anyhow::Result<()> {
    feature_flag::service::log_feature_flags(&app_state.config.feature_flags);
    db::run_migrations(&app_state.database_connection).await?;
    tenant::service::reconcile_system_roles_for_all_tenants(app_state).await?;
    app_state.load_ai_configuration().await;
    startup_seeding::service::run_startup_seeding(app_state).await?;
    Ok(())
}

pub async fn refresh_stale_suggested_questions(app_state: &AppState) {
    scheduler::refresh_all_stale_for_every_tenant(app_state).await;
}

pub async fn run_startup_suggested_question_refresh(app_state: &AppState) {
    scheduler::run_startup_suggested_question_refresh(app_state).await;
}

pub async fn deliver_due_emails(app_state: &AppState) -> anyhow::Result<()> {
    Ok(email_delivery::service::deliver_due_emails(app_state).await?)
}

fn api_router(app_state: AppState) -> Router {
    let tenant_scoped_routes = Router::new()
        .nest("/dashboard", dashboard::routes(app_state.clone()))
        .nest("/connection", connection::routes(app_state.clone()))
        .nest("/notebook", notebook::routes(app_state.clone()))
        .nest("/cell", cell::routes(app_state.clone()))
        .nest("/grant", grant::routes(app_state.clone()))
        .nest("/canvas", canvas::routes(app_state.clone()))
        .nest("/search", search::routes(app_state.clone()))
        .nest(
            "/conversational_analytics",
            conversational_analytics::routes(app_state.clone()),
        )
        .nest(
            "/ai_configuration",
            ai_configuration::routes(app_state.clone()),
        )
        .nest(
            "/suggested_question",
            suggested_question::routes(app_state.clone()),
        )
        .nest("/ai_summary", ai_summary::routes(app_state.clone()))
        .nest(
            "/member",
            tenant::membership::member_routes(app_state.clone()),
        )
        .nest("/role", tenant::membership::role_routes(app_state.clone()))
        .nest(
            "/invitation",
            tenant::invitation::tenant_routes(app_state.clone()),
        );
    let tenant_scoped_routes = behind_the_authentication_guard(&app_state, tenant_scoped_routes);

    Router::new()
        .nest("/api/v1/monitor", monitor::routes())
        .nest("/api/v1/auth", authentication::routes(app_state.clone()))
        .nest("/api/v1/tenant/{tenant_id}", tenant_scoped_routes)
        .nest(
            "/api/v1/tenant",
            behind_the_authentication_guard(&app_state, tenant::routes(app_state.clone())),
        )
        .nest(
            "/api/v1/invitation",
            behind_the_authentication_guard(
                &app_state,
                tenant::invitation::user_routes(app_state.clone()),
            ),
        )
        .nest(
            "/api/v1/invitation_link",
            rate_limit::service::limit_sign_in_requests(
                &app_state.rate_limiters,
                tenant::invitation::link_routes(app_state.clone()),
            ),
        )
        .nest(
            "/api/v1/platform",
            behind_the_authentication_guard(&app_state, platform::routes(app_state.clone())),
        )
}

fn behind_the_authentication_guard(app_state: &AppState, router: Router) -> Router {
    rate_limit::service::limit_api_requests(&app_state.rate_limiters, router).route_layer(
        authorization::service::require_authentication_layer(app_state),
    )
}

pub fn into_service_with_client_address(
    router: Router,
) -> IntoMakeServiceWithConnectInfo<Router, SocketAddr> {
    router.into_make_service_with_connect_info::<SocketAddr>()
}

pub fn build_app(app_state: AppState) -> Router {
    let frontend_dir = PathBuf::from(app_state.config.frontend_dir.as_ref());
    let index_path = frontend_dir.join("index.html");
    let static_files_service = ServeDir::new(&frontend_dir);

    let app = api_router(app_state.clone())
        .fallback_service(static_files_service)
        .layer(middleware::from_fn(move |req: Request, next: Next| {
            let index_path = index_path.clone();
            async move {
                let is_api_request = req
                    .uri()
                    .path()
                    .starts_with(common::constants::API_PATH_PREFIX);
                let res = next.run(req).await;
                let (parts, body) = res.into_parts();
                let status = parts.status;

                if status == StatusCode::NOT_FOUND && !is_api_request {
                    match tokio::fs::read_to_string(&index_path).await {
                        Ok(html) => Html(html).into_response(),
                        Err(_) => Response::from_parts(parts, body),
                    }
                } else {
                    Response::from_parts(parts, body)
                }
            }
        }))
        .layer(TraceLayer::new_for_http())
        .layer(CookieManagerLayer::new())
        .layer(SetResponseHeaderLayer::overriding(
            header::X_CONTENT_TYPE_OPTIONS,
            HeaderValue::from_static(common::constants::CONTENT_TYPE_OPTIONS_HEADER_VALUE),
        ))
        .layer(SetResponseHeaderLayer::overriding(
            header::REFERRER_POLICY,
            HeaderValue::from_static(common::constants::REFERRER_POLICY_HEADER_VALUE),
        ))
        .layer(SetResponseHeaderLayer::overriding(
            header::CONTENT_SECURITY_POLICY,
            HeaderValue::from_static(common::constants::CONTENT_SECURITY_POLICY_HEADER_VALUE),
        ))
        .layer(SetResponseHeaderLayer::overriding(
            header::X_FRAME_OPTIONS,
            HeaderValue::from_static(common::constants::FRAME_OPTIONS_HEADER_VALUE),
        ));

    let cors = if app_state.config.environment == "development" {
        CorsLayer::new()
            .allow_methods([
                Method::GET,
                Method::POST,
                Method::PUT,
                Method::PATCH,
                Method::DELETE,
            ])
            .allow_origin(HeaderValue::from_str("http://localhost").unwrap())
            .allow_credentials(true)
            .allow_headers([header::CONTENT_TYPE])
    } else {
        CorsLayer::new()
            .allow_methods([
                Method::GET,
                Method::POST,
                Method::PUT,
                Method::PATCH,
                Method::DELETE,
            ])
            .allow_credentials(true)
            .allow_headers([header::CONTENT_TYPE])
    };
    app.layer(cors)
}

pub async fn run() -> anyhow::Result<()> {
    dotenv().ok();
    let app_state = AppState::from_env().await?;
    initialize(&app_state).await?;
    scheduler::start(app_state.clone()).await;
    email_delivery::service::start_email_sender(app_state.clone());
    rate_limit::service::start_limiter_cleanup(&app_state.rate_limiters);
    let listener =
        tokio::net::TcpListener::bind(format!("0.0.0.0:{}", app_state.config.port)).await?;
    tracing::debug!("listening on {}", listener.local_addr()?);
    axum::serve(
        listener,
        into_service_with_client_address(build_app(app_state)),
    )
    .await?;
    Ok(())
}
